// math/log2_f64_table.c
//
// rc_log2_f64's table: for each of 256 intervals of the significand m in [1, 2), the c = j / 512
// nearest 1 / m across it, and -log2(c), and its constants. The intervals and c are those of
// rc_log_f64's table. The first interval takes c = 1 and the last c = 1/2, so that around x = 1
// the table adds nothing, and r = m c - 1 stays in [-2^-8.45, 2^-8) everywhere. Generated by
// tools/math/exp_log_f64/gen_tables.py, which chooses each j with exact rationals and rounds
// -log2(c), worked out by mpmath at 300 bits, to a multiple of 2^-42 and the nearest double to
// what is left. 4.5 KiB.

#include "math/exp_log_f64.h"

